*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gNOTI_SVC_ID;
scwin.gAddInput;
scwin.gPvd;
scwin.gIsurCd;
scwin.gTrnsType = 'M'; // N: 쪽지, S: 문자 , M: 이메일, F:팩스
scwin.file_flag = "N";
scwin.gAllChk = false;
scwin.fileSizeLimit = 31457280;
scwin.vScrenID = "ULDSTF07404.xml";
scwin.onpageload = function() {

};
scwin.onpageunload = function() {
};
scwin.fn_SetHeader = function() {
    dts_Master.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_EMAIL_SMS_RECEIVER_INOUT";
    dts_Master.Reset();
    dts_Master.insertRow();
    dts_Receiver.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MAIL_RECEIPTPLACE_OUT";
    dts_Receiver.Reset();

    // 파일: 가우스헤더 셋팅	

    //dts_fileData.setDataHeader();
    //dts_fileData.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_EMAIL_FILE_INOUT";
    //dts_fileData.Reset();
    //dts_fileData.AddRow();	 // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};
scwin.fn_SetData = function() {
    $c.stf.setObjectValue(txb_fromName, "기술상장심사");
    $c.stf.setObjectValue(txb_fromEmail, "krxtechlisting@krx.co.kr");
    $c.stf.setObjectValue(txb_BccName, "기술상장심사");
    $c.stf.setObjectValue(txb_BccEmail, "krxtechlisting@krx.co.kr");
};
scwin.initPage = function() {
    scwin.gNOTI_SVC_ID = $c.stf.getQuery(frame.srcUrl, "NOTI_SVC_ID");
    scwin.gAddInput = $c.stf.getQuery(frame.srcUrl, "ADD_INPUT");
    scwin.gPvd = $c.stf.getQuery(frame.srcUrl, "frameID");
    //alert('[gPvd]'+gPvd);
    //alert('[gNOTI_SVC_ID]'+gNOTI_SVC_ID);
    //alert('[gAddInput]'+gAddInput);
    if (scwin.gAddInput == 'Y') {
        scwin.fn_read();
        scwin.fn_SetData();
    } else {
        scwin.fn_SetHeader();
        scwin.fn_SetData();
    }
};
scwin.fn_read = function() {
    var url = "/EmailMgt.do?method=readSendMailInfo" + "&inputMessageId=BIZSPT_EMAIL_SMS_RECEIVER_INOUT" + "&NOTI_SVC_ID=" + scwin.gNOTI_SVC_ID + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //alert(url);
    dts_Master.DataID = encodeURI(url);
    dts_Master.Reset();
    var urlFile = "/EmailMgt.do?method=listAttachFile" + "&inputMessageId=BIZSPT_EMAIL_SMS_RECEIVER_INOUT" + "&NOTI_SVC_ID=" + scwin.gNOTI_SVC_ID + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //alert(url);
    dts_fileData.DataID = encodeURI(urlFile);
    dts_fileData.Reset();
    var urlReceiver = "/EmailMgt.do?method=listSendReceiver" + "&inputMessageId=BIZSPT_EMAIL_SMS_RECEIVER_INOUT" + "&NOTI_SVC_ID=" + scwin.gNOTI_SVC_ID + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Receiver.DataID = encodeURI(urlReceiver);
    dts_Receiver.Reset();
};


// 첨부파일 다운로드
scwin.fn_filedown = function(vNotiSvcId, vSeq) {
    //var vNotiSvcId= getObjectValue(txb_NOTI_SVC_ID);
    //var vSeq= getObjectValue(txb_file_seq);

    var link = "/filedownload.do?NOTI_SVC_ID=" + vNotiSvcId + "&SEQ=" + vSeq + "&gubun=11";
    location.href = encodeURI(link);
};
scwin.fn_HideDebugCtrls = function() {
    $c.stf.showObj(panel_debug, false);
    //showObj(panel_BCC, false);

};
scwin.fn_registerMail = function() {
    //alert_parse(dts_Receiver.Text, ",");return;
    if (scwin.fn_CheckForm() && scwin.checkFileSize()) {
        var msg = $c.stf.getMessageParam("MSG-A006", "전송");
        var res = window.confirm(msg);
        if (res) {
            var url = "/EmailMgt.do?method=sendSpecyValuEmail" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            //alert(dts_MASTER.Text);
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master, I:pInputDetail=dts_Receiver, I:pFile=dts_fileData)";
            trs_Save.post();
        }
    }
};




/**
 * 전체 파일 사이즈 체크
 */
scwin.checkFileSize = function() {
    var totalFileSize = 0;
    var isValid = true;
    for (var i = 1; i <= dts_fileData.getTotalRow(); i++) {
        totalFileSize = Number(totalFileSize) + Number(dts_fileData.getCellData(i, "FILE_SIZE"));
    }
    if (totalFileSize > scwin.fileSizeLimit) {
        $c.win.alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        isValid = false;
    }
    return isValid;
};
scwin.fn_CheckForm = function() {
    var msg = "";
    if ($c.ut.email_chk($c.stf.getObjectValue(txb_fromEmail)) == false) {
        $c.win.alert("잘못된 이메일 주소입니다.");
        txb_fromEmail.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_title) == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "제목");
        $c.win.alert(msg);
        txb_title.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txa_content) == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "내용");
        $c.win.alert(msg);
        txa_content.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_EMP_NO) == "")	{
    	alert("세션정보를 받지 못했읍니다.");
    	txb_EMP_NO.focus();
    	return false;
    }
    */
    // dts_Receiver 에서 CHECK 된 걸 찾는다.
    var total = 0;
    for (var i = 0; i <= dts_Receiver.getTotalRow(); i++) {
        var chk = dts_Receiver.getCellData(i, "CHECK");
        if (chk == "T" || chk == "1") {
            total++;
        }
    }
    if (total == 0) {
        $c.win.alert("선택된 수신자가 없습니다.");
        return false;
    }
    if (js_svrGubun == 'local' || js_svrGubun == 'dev' || js_svrGubun == 'test1' || js_svrGubun == 'test2') {
        $c.win.alert("◆ 주의 사항 ◆\n\n개발환경에서도 메일이 발송되므로 수신자 메일주소를 확인바랍니다.");
    }
    return true;
};
scwin.fn_Cancel = function() {
    scwin.fn_SetHeader();
    scwin.fn_SetData();
    dts_fileData.removeAll();
};
scwin.fn_SelectAll = function() {
    grd_Receiver.Redraw = false;
    if (scwin.gAllChk == false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        for (var i = 0; i < dts_Receiver.getTotalRow(); i++) {
            dts_Receiver.setCellData(i + 1, "CHECK", "T");
        }
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        for (var i = 0; i < dts_Receiver.getTotalRow(); i++) {
            dts_Receiver.setCellData(i + 1, "CHECK", "F");
        }
        btn_SelectedAll.setValue("전체선택");
    }
    grd_Receiver.Redraw = true;
};



// 첨부파일 다운로드
scwin.fn_filedown = function(vNotiSvcId, vSeq) {
    //var vNotiSvcId= getObjectValue(txb_NOTI_SVC_ID);
    //var vSeq= getObjectValue(txb_file_seq);

    var link = "/filedownload.do?NOTI_SVC_ID=" + vNotiSvcId + "&SEQ=" + vSeq + "&gubun=11";
    location.href = encodeURI(link);
};
scwin.fn_file_click = function() {
    dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", inf_find.getValue());
    txb_file_nm.setValue(inf_find.getValue());
    scwin.file_flag = "Y";
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_Receiver.getCellData(eval(obj), "ISUR_CD");
    //alert("부모창:"+ gIsurCd);

};
scwin.fn_changeTarget = function() {
    var parentWin = $c.frame.path("../");
    var target = $c.stf.getObjectValue(rdo_Target);
    var context, title;
    if (target == "1") {
        //주관사
        title = "(한국거래소) (" + parentWin.getComNm() + ") 전문평가 신청 관련";
        context = "안녕하세요. 한국거래소 기술기업상장부입니다.\n\n" + "신청하신 전문평가 관련 내용이 업데이트되었으니 제출시스템을 통해 확인하시기 바랍니다.\n" + "(전문평가기관 배정된 경우, 당해 기관에 전문평가 신청시 꼭 제출시스템을 통해 신청일을 입력해주시기\n" + "바랍니다. 필요시 미리 수정요청해주시기 바랍니다.)\n\n" + "감사합니다.";
        scwin.fn_setTargetEmail(target);
    } else if (target == "2" || target == "3") {
        //국책기관, TCB
        title = "(한국거래소) (" + parentWin.getComNm() + ") 전문평가 가능여부 회신 요청";
        if (target == "2") {
            context = "안녕하세요. 한국거래소 기술기업상장부(02-3774-9773)입니다.\n\n" + "전문평가대상기업(" + parentWin.getComNm() + ")의 평가대상핵심기술/사업(첨부 참조)에 대해\n" + "이해관계여부(평가이력 등을 미기재하여 신청하는 경우가 있어서 확인 요망),\n" + "일정 등을 고려하여 전문평가 가능여부를 X/XX(X)까지 회신 부탁드립니다.\n\n" + "- 평가가 불가능한 경우에도 \"불가능\"으로 메일 회신을 부탁드리며,\n" + "다수 기관이 평가의사를 밝힐 경우에는 거래소내 배정순번에 따라 평가기관이 배정됩니다.\n\n" + "오늘도 좋은 하루 되시기 바랍니다. 감사합니다!";
        } else if (target == "3") {
            context = "안녕하세요. 한국거래소 기술기업상장부(02-3774-9773)입니다.\n\n" + "전문평가대상기업(" + parentWin.getComNm() + ")의 평가대상핵심기술/사업(첨부 참조)에 대해\n" + "이해관계여부(평가이력 등을 미기재하여 신청하는 경우가 있어서 확인 요망),\n" + "일정 등을 고려하여 전문평가 가능여부를 X/XX(X)까지 회신 부탁드립니다.\n\n" + "- 평가가 불가능한 경우에도 \"불가능\"으로 메일 회신을 부탁드리며,\n\n" + "오늘도 좋은 하루 되시기 바랍니다. 감사합니다!";
        }
        dts_Receiver.removeAll();
    } else if (target == "4") {
        title = "(한국거래소) (" + parentWin.getComNm() + ") 전문평가 배정의 건";
        context = "안녕하세요. 한국거래소 기술기업상장부(02-3774-9773)입니다.\n\n" + "전문평가대상기업(" + parentWin.getComNm() + ")의 전문평가를 귀사가 담당하게 되었음을 알려드립니다.\n" + "(" + parentWin.getAllocationNm() + ")\n\n" + "평가인력이 최종 확정된 후 신청서를 접수하기 바라며,\n" + "신청 접수시까지 평가인력 현황표와 간단한 이력사항, 서약서를 회신해 주시기 바랍니다.\n" + "(저희 소의 감독원 검사 지적사항인 만큼 회신 일자를 지켜서 부탁드리겠습니다.)\n\n" + "기술평가는 신청일로부터 30영업일 이내에 완료될 수 있도록 부탁드리며,\n" + "혹시 평가기간 연장이 필요한 경우 평가기간 만료전에 저희와 협의를 거쳐 처리해 주시기 바랍니다.\n\n" + "기술평가 완료시에는 기술평가서와 이해관계부존재 확인서를 회신해 주시기 바랍니다.\n\n" + "감사합니다.\n";
        dts_Receiver.removeAll();
    }
    txb_title.setValue(title);
    txa_content.text = context;
};
scwin.fn_setTargetEmail = function(vTarget) {
    var parentWin = $c.frame.path("../");
    if (vTarget == "1") {
        //주관사
        var arrInfo = parentWin.getAcptInfo();
        var name = arrInfo[0];
        var email = arrInfo[1];
        //dts_Receiver.ClearData();
        dts_Receiver.insertRow();
        dts_Receiver.setCellData(dts_Receiver.getRowPosition(), "CHRG_NM", name);
        dts_Receiver.setCellData(dts_Receiver.getRowPosition(), "EMAIL", email);
    }
};



/********************************************** 
 * 함수명   : fn_Email
 * 설명      : 전문평가 연락처
 ***********************************************/
scwin.fn_Email = function(arrPar, isFirst) {
    if (isFirst) {
        //dts_Receiver.ClearData();

    }
    dts_Receiver.insertRow();
    dts_Receiver.setCellData(dts_Receiver.getRowPosition(), "CHRG_NM", arrPar[0]);
    dts_Receiver.setCellData(dts_Receiver.getRowPosition(), "EMAIL", arrPar[1]);
};
scwin.fn_formatBytes = function(bytes) {
    if (bytes == 0) return '0 Bytes';
    var k = 1024;
    var sizes = ['Bytes', 'KB', 'MB', 'GB'];
    var i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
};
scwin.grd_Receiver_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.grd_fileList_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.dts_Master_OnLoadError = function() {
    $c.stf.alert_error(dts_Master);
};
scwin.dts_fileData_OnLoadError = function() {
    $c.stf.alert_error(dts_fileData);
};
scwin.dts_Receiver_OnLoadError = function() {
    $c.stf.alert_error(dts_Receiver);
};
scwin.grd_Receiver_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_send_onclick = function() {
    scwin.fn_registerMail();
};
scwin.img_cancel_onclick = function() {
    scwin.fn_Cancel();
};
scwin.img_srch_onclick = async function() {
    fn_SetPar = fn_Email;
    var wth = 1300;
    var hgt = 830;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("", "ULDSTF07403.gfm", "전문평가기관 연락처 관리", pt.x, pt.y, wth, hgt, "window");
};
scwin.trs_Save_OnFail = function() {
    var msg = $c.stf.getMessageParam("MSG-A002", "전송");
    $c.win.alert(msg);
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", "전송");
    $c.win.alert(msg);
    //frame.Provider("../"). fn_Search();
    if (scwin.gPvd) {
        $c.frame.path("../" + scwin.gPvd).fn_Search();
    }
    await $c.frame.CloseFrame();
};
scwin.btn_SelectedAll_onclick = function() {
    scwin.fn_SelectAll();
};
scwin.inf_find_OnClick = function() {
    var filenm = FILE_NAME.value;
    dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", inf_find.getValue());
    txb_file_name.setValue(inf_find.getValue());
    if (inf_find.getValue() == "") {
        txb_file_name.setValue(filenm);
    }
};
scwin.grd_fileList_OnDblClick = function(row, colid) {
    if (dts_fileData.getRowStatus(dts_fileData.getRowPosition()) == 0) {
        scwin.fn_filedown(dts_fileData.getCellData(row, "NOTI_SVC_ID"), dts_fileData.getCellData(row, "FILE_SEQ"));
    }
};
scwin.btn_lineadd_onclick = function() {
    if (dts_fileData.getTotalRow() == 5) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_fileData.insertRow();
    inf_find.open();
    var fileSizeBytes = 0;
    if (inf_find.getValue() != "") {
        var fileName = inf_find.getValue();
        if (fileName.indexOf('\') > 0) {,fileName=fileName.substring(fileName.lastIndexOf('\
                ')+1);,dts_fileData.setCellData(dts_fileData.getRowPosition(),"FILE_NAME",inf_find.getValue()),fileSizeBytes=inf_find.FileInfo("size"),dts_fileData.setCellData(dts_fileData.getRowPosition(),"FILE_SIZE",fileSizeBytes),dts_fileData.setCellData(dts_fileData.getRowPosition(),"FILE_SIZE_VIEW",scwin.fn_formatBytes(fileSizeBytes)),

                ///////////////////////////////////////////////////////
                dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileUrl", inf_find.getValue()), txb_file_name.setValue(inf_find.getValue()))), {
            dts_fileData: dts_fileData
        },
        function() {
            $c.cp.removeRow(dts_fileData, dts_fileData.getRowPosition());
        },
        function() {
            $c.libRoundPanel.PanelToGroupBox(panel_1);
            scwin.fn_HideDebugCtrls();
            scwin.fn_SetHeader();
            scwin.initPage();

            // opener에서 받아온 데이터 세팅
            // 채권담당자조회 화면에서 이 화면을 팝업함. 2022-07-26 by KHJ
            //fn_SetDataFromOpener();

        },
        function() {
            scwin.fn_changeTarget();
        },
        function() {
            dts_Receiver.insertRow();
        },
        function() {
            $c.cp.removeRow(dts_Receiver, dts_Receiver.getRowPosition());
        }))

}
};
